package negocio;
public class TorneoGrupoIntegrante { private long id,grupoId,inscripcionId; private boolean cabezaSerie; private int ordenSorteo; private String nombrePareja; public long getId(){return id;} public void setId(long v){id=v;} public long getGrupoId(){return grupoId;} public void setGrupoId(long v){grupoId=v;} public long getInscripcionId(){return inscripcionId;} public void setInscripcionId(long v){inscripcionId=v;} public boolean isCabezaSerie(){return cabezaSerie;} public void setCabezaSerie(boolean v){cabezaSerie=v;} public int getOrdenSorteo(){return ordenSorteo;} public void setOrdenSorteo(int v){ordenSorteo=v;} public String getNombrePareja(){return nombrePareja;} public void setNombrePareja(String v){nombrePareja=v;} public String toString(){return (cabezaSerie?"★ ":"")+nombrePareja;} }
